/** ComfyUI-style node workspace using the host's controls, colors and React identity. */
import { ReactFlow, Background, MiniMap, NodeResizer, Handle, BaseEdge, getBezierPath, Position, SelectionMode, type Node, type NodeProps, type Edge, type EdgeProps, type ReactFlowInstance } from '@xyflow/react'
import { canConnect, nodeFingerprint, nodeId, canvasId, ports, type CanvasDocument, type CanvasNode, type NodeKind, type NodeId, type NodeExecution, type CanvasRun } from '../shared/canvas.ts'
import { dimensionSchema, type AnalysisRecord, type GenerationRecord } from '../shared/model.ts'
import { acceptedImageTypes } from './import.ts'
import type { CanvasWorkspace, CanvasState } from './canvas-workspace.ts'
import type { Text, TextKey } from './locale.ts'
import type { CanvasField } from '../shared/canvas-validation.ts'

export interface CanvasWorkbenchProps { useWorkspace(): CanvasState; actions: CanvasWorkspace; t: Text; referenceUrl(analysisId: string, referenceId: string): string; openModelSettings(): void }
type PendingConnection = { nodeId: NodeId; handle: string; side: 'source' | 'target' }
type CardData = { graph: CanvasDocument; readOnly: boolean; openModelSettings(): void; node: CanvasNode; state: CanvasState; actions: CanvasWorkspace; t: Text; execution: NodeExecution | undefined; run: CanvasRun | undefined; previous: CanvasRun | undefined; chooseFiles(id: NodeId): void; imageUrl(run: CanvasRun, node: NodeExecution, index: number, original?: boolean): string }
type FlowNode = Node<CardData, 'style'>
type FlowEdge = Edge<{ running: boolean }, 'style'>
const kinds: NodeKind[] = ['reference', 'analysis', 'rules', 'brief', 'prompt', 'image', 'output']

function analysisFor(state: CanvasState, graph: CanvasDocument, id: NodeId, snapshot?: CanvasRun): AnalysisRecord | undefined {
  const visited = new Set<NodeId>(), pending = [id]
  while (pending.length) {
    const next = pending.shift()!
    if (visited.has(next)) continue
    visited.add(next)
    const node = graph.nodes.find(node => node.id === next)
    if (node?.kind === 'analysis') {
      const taskIds = [node.historyTaskId, ...(snapshot ? [snapshot] : state.runs).flatMap(run => run.nodes).filter(node => node.nodeId === next).map(node => node.analysisId)]
      for (const taskId of taskIds) {
        const record = taskId ? state.records[taskId] : undefined
        if (record?.kind === 'analysis' && record.result) return record
      }
    }
    pending.push(...graph.edges.filter(edge => edge.target === next).map(edge => edge.source))
  }
  return undefined
}

function historyGeneration(state: CanvasState, graph: CanvasDocument, id: NodeId): GenerationRecord | undefined {
  const node = graph.nodes.find(node => node.id === id)
  const edge = node?.kind === 'output' ? graph.edges.find(edge => edge.target === id && edge.targetHandle === 'prompt') : undefined
  const source = edge ? graph.nodes.find(node => node.id === edge.source) : node
  const record = source?.kind === 'prompt' && source.historyTaskId ? state.records[source.historyTaskId] : undefined
  return record?.kind === 'generation' ? record : undefined
}

