    const picker = React.useRef<HTMLInputElement>(null), workflowPicker = React.useRef<HTMLInputElement>(null), target = React.useRef<NodeId | undefined>(undefined), container = React.useRef<HTMLDivElement>(null), searchInput = React.useRef<HTMLInputElement>(null), reconnecting = React.useRef<string | null>(null)
